 5	public final class KmpSearch {
 6	
 7	    private KmpSearch() {
 8	        // Utility class.
 9	    }
10	
11	    /**
12	     * Returns the zero-based starting indices of every occurrence of {@code pattern} in {@code text}.
13	     *
14	     * @param pattern the non-empty pattern to search for
15	     * @param text the text to search within
16	     * @return a list of match starting indices in ascending order
17	     * @throws NullPointerException if {@code pattern} or {@code text} is null
18	     * @throws IllegalArgumentException if {@code pattern} is empty
19	     */
20	    public static List<Integer> search(String pattern, String text) {
21	        validateInputs(pattern, text);
22	
23	        if (pattern.length() > text.length()) {
24	            return List.of();
25	        }
26	
27	        int[] longestPrefixSuffix = buildLongestPrefixSuffixTable(pattern);
28	        List<Integer> matches = new ArrayList<>();
29	
30	        int textIndex = 0;
31	        int patternIndex = 0;
32	
33	        while (textIndex < text.length()) {
34	            if (text.charAt(textIndex) == pattern.charAt(patternIndex)) {
35	                textIndex++;
36	                patternIndex++;
37	
38	                if (patternIndex == pattern.length()) {
39	                    matches.add(textIndex - patternIndex);
40	                    patternIndex = longestPrefixSuffix[patternIndex - 1];
41	                }
42	                continue;
43	            }
44	
45	            if (patternIndex > 0) {
46	                patternIndex = longestPrefixSuffix[patternIndex - 1];
47	            } else {
48	                textIndex++;
49	            }
50	        }
51	
52	        return matches;
53	    }
54	
55	    static int[] buildLongestPrefixSuffixTable(String pattern) {
56	        Objects.requireNonNull(pattern, "pattern must not be null");
57	
58	        int[] longestPrefixSuffix = new int[pattern.length()];
59	        int prefixLength = 0;
60	        int currentIndex = 1;
61	
62	        while (currentIndex < pattern.length()) {
63	            if (pattern.charAt(currentIndex) == pattern.charAt(prefixLength)) {
64	                longestPrefixSuffix[currentIndex] = ++prefixLength;
65	                currentIndex++;
66	                continue;
67	            }
68	
69	            if (prefixLength > 0) {
70	                prefixLength = longestPrefixSuffix[prefixLength - 1];
71	            } else {
72	                longestPrefixSuffix[currentIndex] = 0;
73	                currentIndex++;
74	            }
75	        }
76	
77	        return longestPrefixSuffix;
78	    }
79	
80	    private static void validateInputs(String pattern, String text) {
81	        Objects.requireNonNull(pattern, "pattern must not be null");
82	        Objects.requireNonNull(text, "text must not be null");
83	
84	        if (pattern.isEmpty()) {
85	            throw new IllegalArgumentException("pattern must not be empty");
86	        }
